import{_ as s,o as p,c as e,a2 as t}from"./chunks/framework.EUByU7Iq.js";const z=JSON.parse('{"title":"株昭","description":"","frontmatter":{"title":"株昭","date":"2026-11-24T00:00:00.000Z","seq":47,"categories":["美文","楚辞"],"collection":"《楚辞》","tags":["楚辞","先秦"],"poem":true,"poem_quote":false,"author":"王褒","source_book":"楚辞","prev":{"text":"陶壅","link":"/blogs/楚辞/陶壅.html"},"next":{"text":"逢纷","link":"/blogs/楚辞/逢纷.html"}},"headers":[],"relativePath":"blogs/楚辞/株昭.md","filePath":"blogs/楚辞/株昭.md"}'),o={name:"blogs/楚辞/株昭.md"};function l(n,a,c,m,r,_){return p(),e("div",null,[...a[0]||(a[0]=[t('<h1 id="株昭" tabindex="-1">株昭 <a class="header-anchor" href="#株昭" aria-label="Permalink to &quot;株昭&quot;">​</a></h1><p class="poem-meta">先秦 · 王褒　·　九怀</p><div class="poem"><p class="poem-stanza">悲哉于嗟兮，心内切磋。</p><p class="poem-stanza">款冬而生兮，凋彼叶柯。</p><p class="poem-stanza">瓦砾进宝兮，捐弃随和。</p><p class="poem-stanza">铅刀厉御兮，顿弃太阿。</p><p class="poem-stanza">骥垂两耳兮，中坂蹉跎。</p><p class="poem-stanza">蹇驴服驾兮，无用日多。</p><p class="poem-stanza">修洁处幽兮，贵宠沙劘。</p><p class="poem-stanza">凤皇不翔兮，鹑鴳飞扬。</p><p class="poem-stanza">乘虹骖蜺兮，载云变化。</p><p class="poem-stanza">焦明开路兮，后属青蛇。</p><p class="poem-stanza">步骤桂林兮，超骧卷阿。</p><p class="poem-stanza">丘陵翔儛兮，谿谷悲歌。</p><p class="poem-stanza">神章灵篇兮，赴曲相和。</p><p class="poem-stanza">余私娱兹兮，孰哉复加。</p><p class="poem-stanza">还顾世俗兮，坏败罔罗。</p><p class="poem-stanza">卷佩将逝兮，涕流滂沲。</p><p class="poem-stanza">乱曰：皇门开兮照下土，株秽除兮兰芷睹。</p><p class="poem-stanza">四佞放兮後得禹，圣舜摄兮昭尧绪，孰能若兮原为辅。</p></div>',3)])])}const d=s(o,[["render",l]]);export{z as __pageData,d as default};
